#include "unity.h"
#include "buffer.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_compact_shrinks_buffer_to_logical_length(void) {
    // Setup: Create a buffer with extra capacity and some data
    // For example, buffer contains "hello" (length 5), but allocated size is 16
    const char *initial_data = "hello";
    buffer_t *buf = helper_make_buffer_with_size(16);
    TEST_ASSERT_NOT_NULL(buf);
    // Copy "hello" into buffer's data
    memcpy(buf->data, initial_data, strlen(initial_data) + 1); // include null terminator

    // Confirm initial state
    helper_assert_buffer_data_equals(buf, initial_data);
    helper_assert_buffer_length(buf, strlen(initial_data));
    helper_assert_buffer_size(buf, 16);

    // Test: Compact the buffer
    ssize_t removed = buffer_compact(buf);

    // Assertions
    // Should have removed 16 - 5 = 11 bytes
    TEST_ASSERT_EQUAL_INT(11, removed);
    helper_assert_buffer_data_equals(buf, initial_data);
    helper_assert_buffer_length(buf, strlen(initial_data));
    helper_assert_buffer_size(buf, strlen(initial_data)); // Now size should match string length

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_compact_shrinks_buffer_to_logical_length);
    return UNITY_END();
}

